  @Test void copySerialVersion() throws Exception {
    for (Field field : ImmutableSomeSer.class.getDeclaredFields()) {
      field.setAccessible(true);
      if (field.getName().equals("serialVersionUID") && field.get(null).equals(1L)) {
        return;
      }
